{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "N_M_bounds",
      "expression": "1 <= N, M <= 2*10^5",
      "description": "The sizes of arrays A and B are between 1 and 2*10^5."
    },
    {
      "id": "A_B_values",
      "expression": "-10^9 <= A[i], B[i] <= 10^9",
      "description": "The elements of arrays A and B are integers within the specified range."
    }
  ],
  "postconditions": [
    {
      "id": "min_swaps",
      "expression": "output == min_swaps(A, B)",
      "description": "The output is the minimum number of swaps required to move all elements in B to A using the described method."
    }
  ],
  "invariants": []
}
